response = client.messages.create(
    model="claude-sonnet-4-6",
    max_tokens=1024,
    messages=[{
        "role": "user",
        "content": "What is the Latin word for ant? (A) Apoidea (B) Formicidae",
    }],
    tool_choice={"type": "tool", "name": "answer"},
    tools=[{
        "name": "answer",
        "description": "Records the chosen option",
        "strict": True,
        "input_schema": {
            "type": "object",
            "properties": {
                "choice": {"type": "string", "enum": ["A", "B"]}
            },
            "required": ["choice"],
            "additionalProperties": False,
        },
    }],
)
# response.content[0].input == {"choice": "B"} — guaranteed, no text parsing needed

response = client.messages.create(
    model="claude-sonnet-4-6",
    max_tokens=1024,
    messages=[{
        "role": "user",
        "content": "Extract the name and email from: Juan Pérez, juan@email.com",
    }],
    output_config={
        "format": {
            "type": "json_schema",
            "schema": {
                "type": "object",
                "properties": {
                    "name": {"type": "string"},
                    "email": {"type": "string"},
                },
                "required": ["name", "email"],
                "additionalProperties": False,
            },
        }
    },
)
# response.content[0].text is guaranteed valid JSON, ready for json.loads()
import json
data = json.loads(response.content[0].text)
print(data["name"])   # "Juan Pérez"
print(data["email"])  # "juan@email.com"

